"""snapring_exact: parametric CadQuery model generated by stl2cad (exact mode, 2.5D).

The part is built along +y from 1 extrusion(s) and 0 cut(s), applied in order;
each is an outline in the xz plane between two levels. Units: mm.
Run:  python snapring_exact.py [out.step]
"""

import math
import sys

from cadquery import Edge, Face, Solid, Vector, Wire
from cadquery import func as cf

# ---- parameters ----------------------------------------------------------
z0 = 0.0    # level along y
z1 = 9.0    # level along y

DIR = (0, 1, 0)


def P(a, b):
    """Point (x, z) in the sketch plane (y = 0)."""
    return (a, 0, b)


def prism(outline, lo, hi):
    """Outline extruded from level lo to level hi."""
    body = cf.extrude(cf.face(outline), [(hi - lo) * c for c in DIR])
    return body.translate(Vector(*[lo * c for c in DIR]))


def hole(a, b, d, lo, hi):
    return prism(Edge.makeCircle(d / 2, P(a, b), DIR), lo, hi)


# ---- 1. extrusion: y 0.0 to 9.0 ------------------------------
outline_1 = cf.wire(
    Edge.makeThreePointArc(P(-0.75, 26.4893846663), P(0.0, -26.5), P(0.75, 26.4893846663)),
    cf.segment(P(0.75, 26.4893846663), P(0.75, 17.4839211849)),
    Edge.makeThreePointArc(P(0.75, 17.4839211849), P(17.4673263441, 1.0688827763), P(0.75, -17.4839211849)),
    cf.segment(P(0.75, -17.4839211849), P(0.75, -21.0)),
    cf.segment(P(0.75, -21.0), P(-0.75, -21.0)),
    cf.segment(P(-0.75, -21.0), P(-0.75, -17.4839211849)),
    Edge.makeThreePointArc(P(-0.75, -17.4839211849), P(-17.4673263441, 1.0688827763), P(-0.75, 17.4839211849)),
    cf.segment(P(-0.75, 17.4839211849), P(-0.75, 26.4893846663)),
)
part = prism(outline_1, z0, z1)

# ---- revolved features about axes along y: a profile in the half plane through the
# axis (u = distance from the axis, v = level), revolved 360 degrees --------------
RADIAL = (1, 0, 0)


def revolved(axis, rings):
    """Profile rings (outline first, then holes) revolved about the axis through axis along DIR."""
    face = Face.makeFromWires(Wire.assembleEdges(rings[0]), [Wire.assembleEdges(r) for r in rings[1:]])
    return Solid.revolve(face, 360.0, Vector(*axis), Vector(*axis) + Vector(*DIR))

# revolved cut 1
for a, b in [(0.0, 0.0)]:
    axis = P(a, b)
    Q = lambda u, v: Vector(*axis) + Vector(*RADIAL) * u + Vector(*DIR) * v
    rings = [
        [
            Edge.makeLine(Q(26.5, 1.0000050001), Q(26.5, 0.0)),
            Edge.makeLine(Q(26.5, 0.0), Q(25.500007, 0.0)),
            Edge.makeLine(Q(25.500007, 0.0), Q(26.5, 1.0000050001)),
        ],
    ]
    part = part - revolved(axis, rings)

# revolved cut 2
for a, b in [(0.0, 0.0)]:
    axis = P(a, b)
    Q = lambda u, v: Vector(*axis) + Vector(*RADIAL) * u + Vector(*DIR) * v
    rings = [
        [
            Edge.makeLine(Q(25.499994, 9.0), Q(26.5, 9.0)),
            Edge.makeLine(Q(26.5, 9.0), Q(26.5, 7.999995)),
            Edge.makeLine(Q(26.5, 7.999995), Q(25.499994, 9.0)),
        ],
    ]
    part = part - revolved(axis, rings)

# revolved cut 3
for a, b in [(0.0, 0.0)]:
    axis = P(a, b)
    Q = lambda u, v: Vector(*axis) + Vector(*RADIAL) * u + Vector(*DIR) * v
    rings = [
        [
            Edge.makeLine(Q(17.5, 0.999996), Q(18.499996, 0.0)),
            Edge.makeLine(Q(18.499996, 0.0), Q(17.5, 0.0)),
            Edge.makeLine(Q(17.5, 0.0), Q(17.5, 0.999996)),
        ],
    ]
    part = part - revolved(axis, rings)

# revolved cut 4
for a, b in [(0.0, 0.0)]:
    axis = P(a, b)
    Q = lambda u, v: Vector(*axis) + Vector(*RADIAL) * u + Vector(*DIR) * v
    rings = [
        [
            Edge.makeLine(Q(17.5, 8.000004), Q(17.5, 9.0)),
            Edge.makeLine(Q(17.5, 9.0), Q(18.499996, 9.0)),
            Edge.makeLine(Q(18.499996, 9.0), Q(17.5, 8.000004)),
        ],
    ]
    part = part - revolved(axis, rings)

# ---- off-axis bosses and holes: (start point, axis direction, diameter, length) ----
for p, u, d, h, op in [
    ((-7.1, 4.5, 21.99), (1.0, 0.0, 0.0), 4.0, 6.45, "cut"),
    ((0.65, 4.5, 21.99), (1.0, 0.0, 0.0), 4.0, 6.45, "cut"),
    ((-18.63667, 4.5, 21.99), (1.0, 0.0, 0.0), 6.0, 11.63667, "cut"),
    ((18.63667, 4.5, 21.99), (-1.0, 0.0, 0.0), 6.0, 11.63667, "cut"),
]:
    c = Solid.makeCylinder(d / 2, h, Vector(*p), Vector(*u))
    part = part + c if op == "add" else part - c

part = part.clean()

if __name__ == "__main__":
    part.exportStep(sys.argv[1] if len(sys.argv) > 1 else "snapring_exact.step")
